import {distanceKm} from './search-model.js';
import {finite,angle} from './model.js';
import {profiles} from './profiles/catalog.js';
export const normalizeName=s=>String(s).toLowerCase().normalize('NFKD').replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
export function findProfile(spot){const n=normalizeName(spot.name);return profiles.find(p=>distanceKm(spot,p)<=p.radius&&(spot.id===p.id||p.aliases.some(a=>n===normalizeName(a)||n.startsWith(normalizeName(a)+' '))))||null;}
export function profileMatches(q){const n=normalizeName(q);return n.length<3?[]:profiles.filter(p=>p.aliases.some(a=>normalizeName(a).includes(n))||normalizeName(p.name+' '+p.region).includes(n));}
export function matchArticle(spot,pages){const n=normalizeName(spot.name);return pages.find(p=>{const c=p.coordinates?.[0];if(!c||distanceKm(spot,c)>1.5)return false;const title=normalizeName(p.title);return n===title||title.startsWith(n+' ')||n.startsWith(title+' ');})||null;}
export function emptyProfile(spot){return {name:spot.name,bottom:'unknown',character:'unknown',learning:'unknown',facts:[],unknowns:['Surf-zone bottom, exposure and tide response','Current rips, closures, crowding and water quality'],scope:'Automatic lookup for this search result; no local review.',automatic:true};}
export function mapFacts(element){const t=element?.tags||{},source=element?`https://www.openstreetmap.org/${element.type}/${element.id}`:null;const facts=[];const add=(key,label,text)=>facts.push({key,label,text,source,publisher:'OpenStreetMap contributors · community map',confidence:'Low'});if(t.natural==='beach')add('map','Mapped feature','Mapped as a beach. This identifies a shoreline feature, not a surfable break.');if(t.surface)add('surface','Shore surface',`Map surface: ${t.surface}. This is not evidence of the submerged surf-zone bottom.`);if(t.sport?.split(';').includes('surfing'))add('sport','Mapped activity','Surfing is tagged at this feature. This does not establish current access or suitability.');return facts;}
// Only exact-location article leads supply automatic surf context. No free-form content executes.
export function articleContext(profile,page){if(!page)return profile;const text=page.extract||'',source=`https://en.wikipedia.org/?curid=${page.pageid}`;const facts=[...profile.facts];const surfSentence=text.split(/(?<=[.!?])\s+/).find(s=>/\b(surf|wave|break)\w*\b/i.test(s)&&/\b(reef break|beach break|gentle waves|slower.breaking|longboarders)\b/i.test(s));
if(surfSentence){const risky=/\breef break\b/i.test(surfSentence);const soft=/gentle waves|slower.breaking|longboarders/i.test(surfSentence);facts.push({key:'automatic-context',label:'Automatically found surf context',text:surfSentence.slice(0,450),source,publisher:'Wikipedia contributors · automatic excerpt',confidence:'Low'});if(profile.automatic){profile={...profile,character:soft?'soft':profile.character,bottom:risky?'rock':profile.bottom};}}
return {...profile,facts,article:{title:page.title,source,excerpt:text.slice(0,500),updated:page.touched}};}
export function recommend(profile,c,level,board,now=Date.now()){
const reasons=[],unknowns=[...profile.unknowns];const out={title:'Check locally before choosing a session',tone:'caution',confidence:'Low',reasons,unknowns,boardTitle:'Board fit is conditional',board:'Actual face shape and your ability matter more than board length alone.'};
if(!c||now-c.fetched>30*60e3||!['height','swell','period','direction','wind','windDirection','day'].every(k=>finite(c[k]))){return {...out,title:'Recommendation paused',tone:'avoid',boardTitle:'Wait for complete forecasts',board:'No board recommendation from missing or stale forecast values.',reasons:['Complete, recent marine and wind data are required. Refresh forecasts.']};}
let skip=false;const add=(text,stop=false)=>{reasons.push(text);skip ||= stop;};
if(!c.day)add('This forecast hour is outside daylight. Choose a daytime window.',true);
if(c.height>({beginner:.8,intermediate:1.8,advanced:2.8}[level]??.8))add('Offshore wave height exceeds the experimental screening limit for your experience. Actual surf may be larger or smaller.',true);
if(c.wind>=20)add('Strong modeled wind makes this a poor candidate for all profiles.',true);
else if(c.wind>=12)add('Modeled wind may disrupt wave faces and paddling, even if offshore.');
if(level==='beginner'&&(c.period>=13||c.wind>10))add('Period or wind exceeds the conservative beginner screen.',true);
if(c.period>=14)add('Long-period swell may focus and steepen over the local bottom; small offshore height does not ensure gentle surf.');
if(profile.bottom==='rock'){add('Sourced reef context: water depth over rock is unknown. Check sets, entry and exit before considering the session.');if(level==='beginner')add('Rocky reef is outside this app’s beginner recommendation set.',true);if(finite(c.tide)&&c.tide<.6)add('Low water at the regional tide station adds reef-clearance concern. This threshold is a precaution, not measured local depth.',true);}
if(level==='beginner'&&profile.learning!=='lesson')add('There is not enough reviewed local evidence to recommend this break to a beginner. Arrange a local lesson.',true);
if(finite(profile.normal)){const a=angle(c.windDirection,profile.normal);if(c.wind>=6&&a<60)add('Wind is approximately onshore here and may add chop. Shoreline orientation is a map-based estimate.');if(angle(c.direction,profile.normal)>85)add('Swell is oblique to the approximate shoreline. Delivery at the break is uncertain.');}
if(c.swell<.35)add('Very little modeled swell: there may be limited rideable surf.');
if(!finite(c.tide))unknowns.push('Tide predictions unavailable for this hour');
if(profile.automatic)unknowns.push('Automatic source matching has not been reviewed locally');
if(profile.bottom==='unknown')unknowns.push('Submerged bottom remains unknown');
if(!skip){if(profile.character==='soft'){out.boardTitle=board==='foam'?'Your foam board fits the reported softer style':'Favor glide on the reported softer waves';out.board=board==='foam'?'Your 8′ foam board offers early entry and stability if today’s faces match the slower-breaking description. Confirm room to control it in the lineup.':board==='fish'?'Your 5′10″ fish can carry speed on an open face, but a longer board may catch soft waves earlier. A fish is not automatically ideal just because it is under 6 feet.':'Your 29 L shortboard needs more push than a longer board. If today matches the reported softer style, expect fewer wave-catching opportunities.';}else{out.boardTitle=board==='foam'?'Favor manageable, open faces':board==='fish'?'Your fish needs a makeable open face':'Your shortboard needs usable push';out.board=board==='foam'?'An 8′ foam board offers glide and stability. Steep takeoffs and crowded peaks still require control; foam does not remove hazards.':board==='fish'?'A wide, low-rocker fish can retain speed on smaller peeling waves. The forecast does not establish whether today’s bank is peeling, hollow or closing out.':'A 6′, 29 L shortboard needs enough face speed and paddle fitness. Offshore wave height alone cannot establish that fit.';}
if(level==='beginner'){out.boardTitle='Consider a local lesson, not an independent surf call';out.board='Favor a suitable foam board and instructor-selected whitewater. The forecast and a general learning reputation cannot establish today’s safety.';}
if(!profile.automatic&&profile.bottom!=='unknown'&&finite(c.tide)&&c.period<14){out.confidence='Moderate';}
out.title=profile.automatic?'Limited evidence · conditional board advice':level==='beginner'?'Discuss this window with an instructor':'Potential fit · verify at the beach';
}else{out.title='Not recommended for this profile / hour';out.tone='avoid';out.boardTitle='A different board does not resolve this';out.board='Address the conditions or experience concerns above before selecting equipment.';}
if(!reasons.length)reasons.push('The forecast passes the initial experience screen; local wave faces, currents and hazards still need an on-site check.');
return out;
}
